 14→// setupDiscoveryDir creates a temp directory containing a mock entire-agent-<name> binary.
 15→// Returns the directory path.
 16→func setupDiscoveryDir(t *testing.T, agentName, infoJSON string) string {
 17→	t.Helper()
 18→
 19→	dir := t.TempDir()
 20→	binName := binaryPrefix + agentName
 21→	binPath := filepath.Join(dir, binName)
 22→
 23→	script := mockInfoScript(infoJSON)
 24→	if err := os.WriteFile(binPath, []byte(script), 0o755); err != nil {
 25→		t.Fatalf("write mock binary: %v", err)
 26→	}
 27→	return dir
 28→}
