 30→func makeInfoJSON(name string) string {
 31→	return `{
 32→  "protocol_version": 1,
 33→  "name": "` + name + `",
 34→  "type": "` + name + ` Agent",
 35→  "description": "Agent ` + name + `",
 36→  "is_preview": false,
 37→  "protected_dirs": [],
 38→  "hook_names": [],
 39→  "capabilities": {}
 40→}`
