 46→// enableExternalAgents creates a temp repo with external_agents enabled in settings
 47→// and chdir's into it so that settings.Load can find the config.
 48→func enableExternalAgents(t *testing.T) {
 49→	t.Helper()
 50→	tmpDir := t.TempDir()
 51→	if err := os.MkdirAll(filepath.Join(tmpDir, ".git"), 0o755); err != nil {
 52→		t.Fatalf("create .git: %v", err)
 53→	}
 54→	entireDir := filepath.Join(tmpDir, ".entire")
 55→	if err := os.MkdirAll(entireDir, 0o755); err != nil {
 56→		t.Fatalf("create .entire: %v", err)
 57→	}
 58→	if err := os.WriteFile(filepath.Join(entireDir, "settings.json"), []byte(`{"enabled":true,"external_agents":true}`), 0o644); err != nil {
 59→		t.Fatalf("write settings: %v", err)
 60→	}
 61→	t.Chdir(tmpDir)
 62→}
