110→func TestDiscoverAndRegister_SkipsNameConflict(t *testing.T) {
111→	if _, err := exec.LookPath("sh"); err != nil {
112→		t.Skip("sh not available")
113→	}
114→
115→	enableExternalAgents(t)
116→
117→	name := "disc-conflict"
118→	// Pre-register an agent with the same name.
119→	agent.Register(types.AgentName(name), func() agent.Agent {
120→		return nil // placeholder
121→	})
122→
123→	// Create an external binary with the conflicting name, using a different type.
124→	conflictJSON := `{
125→  "protocol_version": 1,
126→  "name": "` + name + `",
127→  "type": "Different Type",
128→  "description": "Should be skipped",
129→  "is_preview": false,
130→  "protected_dirs": [],
131→  "hook_names": [],
132→  "capabilities": {}
133→}`
134→	dir := setupDiscoveryDir(t, name, conflictJSON)
135→	t.Setenv("PATH", dir)
136→
137→	DiscoverAndRegister(context.Background())
138→
139→	// The pre-registered placeholder should still be there (returns nil).
140→	ag, err := agent.Get(types.AgentName(name))
141→	if err != nil {
142→		t.Fatalf("agent should still be registered: %v", err)
143→	}
144→	// The placeholder factory returns nil, so it wasn't replaced by the external one.
145→	if ag != nil {
146→		t.Errorf("expected placeholder (nil) agent, got %v", ag)
147→	}
148→}
